    private static final Linker LINKER = Linker.nativeLinker();
    private static final SymbolLookup LOADER =
            SymbolLookup.libraryLookup("libvulkan.so.1", Arena.global());

    private static MethodHandle core(String name, FunctionDescriptor descriptor, boolean critical) {
        MemorySegment address = LOADER.find(name)
                .orElseThrow(() -> new UnsatisfiedLinkError("Vulkan command not found: " + name));
        return critical
                ? LINKER.downcallHandle(address, descriptor, Linker.Option.critical(false))
                : LINKER.downcallHandle(address, descriptor);
    }

    private static MethodHandle resolved(MemorySegment address, FunctionDescriptor descriptor,
                                         boolean critical) {
        if (address.equals(MemorySegment.NULL)) {
            return null;
        }
        return critical
                ? LINKER.downcallHandle(address, descriptor, Linker.Option.critical(false))
                : LINKER.downcallHandle(address, descriptor);
    }

    private static RuntimeException rethrow(Throwable t) {
        if (t instanceof RuntimeException r) {
            return r;
        }
        if (t instanceof Error e) {
            throw e;
        }
        return new RuntimeException(t);
    }

    private static final class H_vkCreateInstance {
        static final MethodHandle MH = core("vkCreateInstance",
                FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS), false);
    }

    public static int vkCreateInstance(MemorySegment pCreateInfo, MemorySegment pAllocator, MemorySegment pInstance) {
        try {
            return (int) H_vkCreateInstance.MH.invokeExact(pCreateInfo, pAllocator, pInstance);
        } catch (Throwable t) {
            throw rethrow(t);
        }
    }

    private static final class H_vkDestroyInstance {
        static final MethodHandle MH = core("vkDestroyInstance",
                FunctionDescriptor.ofVoid(ValueLayout.JAVA_LONG, ValueLayout.ADDRESS), false);
    }

    public static void vkDestroyInstance(long instance, MemorySegment pAllocator) {
        try {
            H_vkDestroyInstance.MH.invokeExact(instance, pAllocator);
        } catch (Throwable t) {
            throw rethrow(t);
        }
    }

