    /**
     * Resolves the commands that are not exported by the loader for a device.
     */
    public static void loadDeviceCommands(long device) {
        try (Arena arena = Arena.ofConfined()) {
            mh_vkCmdPushDescriptorSetKHR = resolved(vkGetDeviceProcAddr(device, arena.allocateFrom("vkCmdPushDescriptorSetKHR")), FD_vkCmdPushDescriptorSetKHR, true);
            mh_vkGetMemoryFdKHR = resolved(vkGetDeviceProcAddr(device, arena.allocateFrom("vkGetMemoryFdKHR")), FD_vkGetMemoryFdKHR, false);
            mh_vkGetSemaphoreFdKHR = resolved(vkGetDeviceProcAddr(device, arena.allocateFrom("vkGetSemaphoreFdKHR")), FD_vkGetSemaphoreFdKHR, false);
        }
    }

    /** Whether a command resolved by {@link #loadDeviceCommands} is available. */
    public static boolean isAvailable(String command) {
        return switch (command) {
            case "vkCmdPushDescriptorSetKHR" -> mh_vkCmdPushDescriptorSetKHR != null;
            case "vkGetMemoryFdKHR" -> mh_vkGetMemoryFdKHR != null;
            case "vkGetSemaphoreFdKHR" -> mh_vkGetSemaphoreFdKHR != null;
            default -> true;
        };
    }
